/* nbody_cuda_crlibm.cuh
 *
 * Vendored crlibm log_rn (correctly-rounded log) for CUDA __device__ code.
 * Lifted from crlibm/log.c, log.h, crlibm_private.h, triple-double.h.
 *
 * Why: crlibm log_rn is what the CPU calls inside mw_log() when CRLIBM=ON.
 * CUDA's __device__ log() differs by ~1 ULP per call, which compounds
 * chaotically over thousands of timesteps and inflates per-bin Beta/Vel
 * histogram metrics beyond the 1e-4 validator spec on long WUs.
 *
 * This header is single-TU: all symbols are __device__ static; include
 * exactly once in nbody_cuda.cu. Replace `log(x)` calls in __device__
 * code with `cuda_crlibm_log_rn(x)`.
 *
 * Little-endian assumption (HI=1, LO=0) — true for x86_64, aarch64, and
 * all CUDA targets we care about.
 */

#ifndef NBODY_CUDA_CRLIBM_CUH
#define NBODY_CUDA_CRLIBM_CUH 1

#include <stdint.h>

/* -------- types -------- */

typedef union {
    int32_t i[2];
    int64_t l;
    double  d;
} cuda_db_number;

typedef struct {
    float  ri;
    double logih;
    double logim;
    double logil;
} cuda_rri;

#define CUDA_HI 1
#define CUDA_LO 0

