/* -------- Dekker double-double primitives ----------
 * All taken verbatim from crlibm/crlibm_private.h, with the AVOID_BRANCHES=1
 * branch for Add12Cond and the non-FMA Dekker form for Mul12/Mul22.
 * (x86_64 crlibm uses these because PROCESSOR_HAS_FMA is only set on
 * PowerPC/Itanium.)
 *
 * These are macros, so they expand inline inside __device__ functions
 * with no function-call overhead.
 */

#define CUDA_Add12(s, r, a, b)              \
    {                                       \
        double _z, _a = (a), _b = (b);      \
        s = _a + _b;                        \
        _z = s - _a;                        \
        r = _b - _z;                        \
    }

/* AVOID_BRANCHES=1 branchless form */
#define CUDA_Add12Cond(s, r, a, b)          \
    {                                       \
        double _u1, _u2, _u3, _u4;          \
        double _a = (a), _b = (b);          \
        s   = _a + _b;                      \
        _u1 = s - _a;                       \
        _u2 = s - _u1;                      \
        _u3 = _b - _u1;                     \
        _u4 = _a - _u2;                     \
        r   = _u4 + _u3;                    \
    }

#define CUDA_Add22(zh, zl, xh, xl, yh, yl)              \
    do {                                                \
        double _r, _s;                                  \
        _r  = (xh) + (yh);                              \
        _s  = ((((xh) - _r) + (yh)) + (yl)) + (xl);     \
        *(zh) = _r + _s;                                \
        *(zl) = (_r - (*(zh))) + _s;                    \
    } while (0)

#define CUDA_Add22Cond(zh, zl, xh, xl, yh, yl)              \
    do {                                                    \
        double _v1, _v2, _v3, _v4;                          \
        CUDA_Add12Cond(_v1, _v2, (xh), (yh));               \
        _v3 = (xl) + (yl);                                  \
        _v4 = _v2 + _v3;                                    \
        CUDA_Add12((*(zh)), (*(zl)), _v1, _v4);             \
    } while (0)

/* Dekker Mul12 (no FMA path, matches x86_64 crlibm). */
#define CUDA_Mul12(rh, rl, u, v)                                  \
    {                                                             \
        const double _c = 134217729.0; /* 2^27 + 1 */             \
        double _up, _u1, _u2, _vp, _v1, _v2;                      \
        double _u = (u), _v = (v);                                \
        _up = _u * _c;        _vp = _v * _c;                      \
        _u1 = (_u - _up) + _up;  _v1 = (_v - _vp) + _vp;          \
        _u2 = _u - _u1;          _v2 = _v - _v1;                  \
        *(rh) = _u * _v;                                          \
        *(rl) = (((_u1 * _v1 - *(rh)) + (_u1 * _v2)) +            \
                  (_u2 * _v1)) + (_u2 * _v2);                     \
    }

#define CUDA_Mul22(zh, zl, xh, xl, yh, yl)                              \
    {                                                                   \
        double _mh, _ml;                                                \
        const double _c = 134217729.0;                                  \
        double _up, _u1, _u2, _vp, _v1, _v2;                            \
        _up = (xh) * _c;        _vp = (yh) * _c;                        \
        _u1 = ((xh) - _up) + _up;  _v1 = ((yh) - _vp) + _vp;            \
        _u2 = (xh) - _u1;          _v2 = (yh) - _v1;                    \
        _mh = (xh) * (yh);                                              \
        _ml = (((_u1 * _v1 - _mh) + (_u1 * _v2)) +                      \
                (_u2 * _v1)) + (_u2 * _v2);                             \
        _ml += (xh) * (yl) + (xl) * (yh);                               \
        *(zh) = _mh + _ml;                                              \
        *(zl) = _mh - (*(zh)) + _ml;                                    \
    }

#define CUDA_MulAdd22(resh, resl, ch, cl, ah, al, bh, bl)                       \
    {                                                                           \
        double _t1, _t2, _t3, _t4, _t5, _t6, _t7, _t8, _t9, _t10;               \
        CUDA_Mul12(&_t1, &_t2, (ah), (bh));                                     \
        CUDA_Add12(_t3, _t4, (ch), _t1);                                        \
        _t5  = (ah) * (bl);                                                     \
        _t6  = (al) * (bh);                                                     \
        _t7  = _t2 + (cl);                                                      \
        _t8  = _t4 + _t7;                                                       \
        _t9  = _t5 + _t6;                                                       \
        _t10 = _t8 + _t9;                                                       \
        CUDA_Add12((*(resh)), (*(resl)), _t3, _t10);                            \
    }

#define CUDA_Add122(resh, resl, a, bh, bl)              \
    {                                                   \
        double _t1, _t2, _t3;                           \
        CUDA_Add12(_t1, _t2, (a), (bh));                \
        _t3 = _t2 + (bl);                               \
        CUDA_Add12((*(resh)), (*(resl)), _t1, _t3);     \
    }

#define CUDA_Add33(resh, resm, resl, ah, am, al, bh, bm, bl)            \
    {                                                                   \
        double _t1, _t2, _t3, _t4, _t5, _t6, _t7, _t8;                  \
        CUDA_Add12((*(resh)), _t1, (ah), (bh));                         \
        CUDA_Add12Cond(_t2, _t3, (am), (bm));                           \
        _t6 = (al) + (bl);                                              \
        CUDA_Add12Cond(_t7, _t4, _t1, _t2);                             \
        _t5 = _t3 + _t4;                                                \
        _t8 = _t5 + _t6;                                                \
        CUDA_Add12Cond((*(resm)), (*(resl)), _t7, _t8);                 \
    }

#define CUDA_Add133(resh, resm, resl, a, bh, bm, bl)        \
    {                                                       \
        double _t1, _t2, _t3, _t4;                          \
        CUDA_Add12((*(resh)), _t1, (a), (bh));              \
        CUDA_Add12Cond(_t2, _t3, _t1, (bm));                \
        _t4 = _t3 + (bl);                                   \
        CUDA_Add12Cond((*(resm)), (*(resl)), _t2, _t4);     \
    }

#define CUDA_Add23(resh, resm, resl, ah, al, bh, bl)        \
    {                                                       \
        double _t1, _t2, _t3, _t4, _t5, _t6;                \
        CUDA_Add12((*(resh)), _t1, (ah), (bh));             \
        CUDA_Add12Cond(_t2, _t3, (al), (bl));               \
        CUDA_Add12Cond(_t4, _t5, _t1, _t2);                 \
        _t6 = _t3 + _t5;                                    \
        CUDA_Add12Cond((*(resm)), (*(resl)), _t4, _t6);     \
    }

#define CUDA_Mul233(resh, resm, resl, ah, al, bh, bm, bl)               \
    {                                                                   \
        double _t1, _t2, _t3, _t4, _t5, _t6, _t7, _t8, _t9, _t10;       \
        double _t11, _t12, _t13, _t14, _t15, _t16, _t17, _t18;          \
        CUDA_Mul12((resh), &_t1, (ah), (bh));                           \
        CUDA_Mul12(&_t2, &_t3, (ah), (bm));                             \
        CUDA_Mul12(&_t4, &_t5, (ah), (bl));                             \
        CUDA_Mul12(&_t6, &_t7, (al), (bh));                             \
        CUDA_Mul12(&_t8, &_t9, (al), (bm));                             \
        _t10 = (al) * (bl);                                             \
        CUDA_Add22Cond(&_t11, &_t12, _t2, _t3, _t4, _t5);               \
        CUDA_Add22Cond(&_t13, &_t14, _t6, _t7, _t8, _t9);               \
        CUDA_Add22Cond(&_t15, &_t16, _t11, _t12, _t13, _t14);           \
        CUDA_Add12Cond(_t17, _t18, _t1, _t10);                          \
        CUDA_Add22Cond((resm), (resl), _t17, _t18, _t15, _t16);         \
    }

#define CUDA_Renormalize3(resh, resm, resl, ah, am, al)         \
    {                                                           \
        double _t1h, _t1l, _t2l;                                \
        CUDA_Add12(_t1h, _t1l, (am), (al));                     \
        CUDA_Add12((*(resh)), _t2l, (ah), _t1h);                \
        CUDA_Add12((*(resm)), (*(resl)), _t2l, _t1l);           \
    }

/* Returns from the enclosing function (mirrors crlibm semantics). */
#define CUDA_ReturnRoundToNearest3(xh, xm, xl)                          \
    {                                                                   \
        double _t1, _t2, _t3, _t4, _t5, _t6;                            \
        cuda_db_number _xp, _xn;                                        \
        _xp.d = (xh);                                                   \
        _xn.i[CUDA_HI] = _xp.i[CUDA_HI];                                \
        _xn.i[CUDA_LO] = _xp.i[CUDA_LO];                                \
        _xn.l--;                                                        \
        _t1 = _xn.d;                                                    \
        _xp.l++;                                                        \
        _t4 = _xp.d;                                                    \
        _t2 = (xh) - _t1;                                               \
        _t3 = _t2 * -0.5;                                               \
        _t5 = _t4 - (xh);                                               \
        _t6 = _t5 * 0.5;                                                \
        if (((xm) != _t3) && ((xm) != _t6)) return ((xh) + (xm));       \
        if ((xm) * (xl) > 0.0) {                                        \
            if ((xh) * (xl) > 0.0) return _t4;                          \
            else                  return _t1;                           \
        } else return (xh);                                             \
    }

