/* -------- p_accu (slow-path 21-step double-double polynomial) -------- */

__device__ static __forceinline__
void cuda_crlibm_p_accu(double* p_resh, double* p_resm, double* p_resl,
                        double xh, double xm)
{
    double p_t_1_0h;
    double p_t_2_0h;
    double p_t_3_0h;
    double p_t_4_0h;
    double p_t_5_0h;
    double p_t_6_0h;
    double p_t_7_0h;
    double p_t_8_0h;
    double p_t_9_0h, p_t_9_0m;
    double p_t_10_0h, p_t_10_0m;
    double p_t_11_0h, p_t_11_0m;
    double p_t_12_0h, p_t_12_0m;
    double p_t_13_0h, p_t_13_0m;
    double p_t_14_0h, p_t_14_0m;
    double p_t_15_0h, p_t_15_0m;
    double p_t_16_0h, p_t_16_0m, p_t_16_0l;
    double p_t_17_0h, p_t_17_0m, p_t_17_0l;
    double p_t_18_0h, p_t_18_0m, p_t_18_0l;
    double p_t_19_0h, p_t_19_0m, p_t_19_0l;
    double p_t_20_0h, p_t_20_0m, p_t_20_0l;
    double p_t_21_0h, p_t_21_0m, p_t_21_0l;

    p_t_1_0h = CUDA_CRLIBM_pa12h;
    p_t_2_0h = p_t_1_0h * xh;
    p_t_3_0h = CUDA_CRLIBM_pa11h + p_t_2_0h;
    p_t_4_0h = p_t_3_0h * xh;
    p_t_5_0h = CUDA_CRLIBM_pa10h + p_t_4_0h;
    p_t_6_0h = p_t_5_0h * xh;
    p_t_7_0h = CUDA_CRLIBM_pa9h + p_t_6_0h;
    p_t_8_0h = p_t_7_0h * xh;
    CUDA_Add12(p_t_9_0h, p_t_9_0m, CUDA_CRLIBM_pa8h, p_t_8_0h);
    CUDA_MulAdd22(&p_t_10_0h, &p_t_10_0m, CUDA_CRLIBM_pa7h, CUDA_CRLIBM_pa7m, xh, xm, p_t_9_0h, p_t_9_0m);
    CUDA_MulAdd22(&p_t_11_0h, &p_t_11_0m, CUDA_CRLIBM_pa6h, CUDA_CRLIBM_pa6m, xh, xm, p_t_10_0h, p_t_10_0m);
    CUDA_MulAdd22(&p_t_12_0h, &p_t_12_0m, CUDA_CRLIBM_pa5h, CUDA_CRLIBM_pa5m, xh, xm, p_t_11_0h, p_t_11_0m);
    CUDA_Mul22(&p_t_13_0h, &p_t_13_0m, p_t_12_0h, p_t_12_0m, xh, xm);
    CUDA_Add122(&p_t_14_0h, &p_t_14_0m, CUDA_CRLIBM_pa4h, p_t_13_0h, p_t_13_0m);
    CUDA_Mul22(&p_t_15_0h, &p_t_15_0m, p_t_14_0h, p_t_14_0m, xh, xm);
    CUDA_Add23(&p_t_16_0h, &p_t_16_0m, &p_t_16_0l, CUDA_CRLIBM_pa3h, CUDA_CRLIBM_pa3m, p_t_15_0h, p_t_15_0m);
    CUDA_Mul233(&p_t_17_0h, &p_t_17_0m, &p_t_17_0l, xh, xm, p_t_16_0h, p_t_16_0m, p_t_16_0l);
    CUDA_Add133(&p_t_18_0h, &p_t_18_0m, &p_t_18_0l, CUDA_CRLIBM_pa2h, p_t_17_0h, p_t_17_0m, p_t_17_0l);
    CUDA_Mul233(&p_t_19_0h, &p_t_19_0m, &p_t_19_0l, xh, xm, p_t_18_0h, p_t_18_0m, p_t_18_0l);
    CUDA_Add133(&p_t_20_0h, &p_t_20_0m, &p_t_20_0l, CUDA_CRLIBM_pa1h, p_t_19_0h, p_t_19_0m, p_t_19_0l);
    CUDA_Mul233(&p_t_21_0h, &p_t_21_0m, &p_t_21_0l, xh, xm, p_t_20_0h, p_t_20_0m, p_t_20_0l);
    CUDA_Renormalize3(p_resh, p_resm, p_resl, p_t_21_0h, p_t_21_0m, p_t_21_0l);
}

/* -------- log_rn (correctly-rounded log) -------- */

__device__ static __forceinline__
double cuda_crlibm_log_rn(double x)
{
    cuda_db_number xdb, yhdb;
    double yh, yl, ed, ri, logih, logim, logil, yrih, yril, th, zh, zl;
    double ph, pl, pm, log2edh, log2edl, log2edm, logTabPolyh, logTabPolyl, logh, logm, logl;
    int E, index;
    double zhSquare, zhCube, zhSquareHalf;
    double p35, p46, p36;
    double pUpper;
    double zhSquareHalfPlusZl;
    double zhFour;
    double logyh, logym, logyl;
    double loghover, logmover, loglover;

    E = 0;
    xdb.d = x;

    /* Filter cases */
    if (xdb.i[CUDA_HI] < 0x00100000) {        /* x < 2^(-1022)    */
        if (((xdb.i[CUDA_HI] & 0x7fffffff) | xdb.i[CUDA_LO]) == 0) {
            return -1.0 / 0.0;                /* log(+/-0) = -Inf */
        }
        if (xdb.i[CUDA_HI] < 0) {
            return (x - x) / 0.0;             /* log(-x) = NaN    */
        }
        /* Subnormal */
        E = -52;
        xdb.d *= CUDA_CRLIBM_two52;
    }

    if (xdb.i[CUDA_HI] >= 0x7ff00000) {
        return x + x;                          /* Inf or NaN */
    }

    /* Extract exponent and mantissa, range-reduce */
    E += (xdb.i[CUDA_HI] >> 20) - 1023;
    index = (xdb.i[CUDA_HI] & 0x000fffff);
    xdb.i[CUDA_HI] = index | 0x3ff00000;
    index = (index + (1 << (20 - CUDA_CRLIBM_L - 1))) >> (20 - CUDA_CRLIBM_L);

    /* sqrt(2)/2 < xdb.d < sqrt(2) */
    if (index >= CUDA_CRLIBM_MAXINDEX) {
        xdb.i[CUDA_HI] -= 0x00100000;
        E++;
    }

    yhdb.i[CUDA_HI] = xdb.i[CUDA_HI];
    yhdb.i[CUDA_LO] = 0;
    yh = yhdb.d;
    yl = xdb.d - yh;

    index = index & CUDA_CRLIBM_INDEXMASK;
    ed = (double) E;

    ri    = (double) argredtable_cuda[index].ri;
    logih = argredtable_cuda[index].logih;
    logim = argredtable_cuda[index].logim;

    /* zh + zl = y * ri - 1.0 (exact via 21-bit ri + Add12Cond) */
    yrih = yh * ri;
    yril = yl * ri;
    th   = yrih - 1.0;
    CUDA_Add12Cond(zh, zl, th, yril);

    /* Polynomial approximation */
    zhSquare     = zh * zh;
    p35          = CUDA_CRLIBM_p3h + zhSquare * CUDA_CRLIBM_p5h;
    p46          = CUDA_CRLIBM_p4h + zhSquare * CUDA_CRLIBM_p6h;
    zhCube       = zhSquare * zh;
    zhSquareHalf = CUDA_CRLIBM_p2h * zhSquare;
    zhFour       = zhSquare * zhSquare;

    p36                = zhCube * p35 + zhFour * p46;
    zhSquareHalfPlusZl = zhSquareHalf + zl;
    pUpper             = zhSquareHalfPlusZl + p36;

    CUDA_Add12(ph, pl, zh, pUpper);

    /* Reconstruction: log(x) = ed*log2 + log(1+z) - log(ri) */
    CUDA_Add12(log2edh, log2edl, CUDA_CRLIBM_log2h * ed, CUDA_CRLIBM_log2m * ed);

    CUDA_Add22(&logTabPolyh, &logTabPolyl, logih, logim, ph, pl);
    CUDA_Add22(&logh, &logm, log2edh, log2edl, logTabPolyh, logTabPolyl);

    /* Rounding test */
    if (logh == (logh + (logm * CUDA_CRLIBM_RNROUNDCST)))
        return logh;

    /* Slow path */
    logil = argredtable_cuda[index].logil;
    cuda_crlibm_p_accu(&ph, &pm, &pl, zh, zl);

    CUDA_Add33(&logyh, &logym, &logyl, logih, logim, logil, ph, pm, pl);

    log2edh = CUDA_CRLIBM_log2h * ed;
    log2edm = CUDA_CRLIBM_log2m * ed;
    log2edl = CUDA_CRLIBM_log2l * ed;

    CUDA_Add33(&loghover, &logmover, &loglover, log2edh, log2edm, log2edl, logyh, logym, logyl);

    CUDA_Renormalize3(&logh, &logm, &logl, loghover, logmover, loglover);

    CUDA_ReturnRoundToNearest3(logh, logm, logl);
}


/* ===================================================================
 * crlibm pow_rn vendor port (continues nbody_cuda_crlibm.cuh)
 * ===================================================================
 *
 * pow_rn shares argredtable_cuda[256] with log_rn (already defined
 * above). Adds two exp tables (twoPowerIndex1[32], twoPowerIndex2[256]),
 * two more polynomial coefficient sets (log2_70, log2_130 for log,
 * exp2_120 + exp2_p for exp), and four more DD primitive macros.
 *
 * pow_exact_case is intentionally NOT vendored — it handles exact-power
 * special cases (e.g. 4.0^2.0 = 16.0 bit-exact) which never fire for
 * pow(rp, 1.5) with the rp range our integrator produces. If the Ziv
 * test in pow_round_and_check_rn fails, we fall back to CUDA __device__
 * pow as a last resort (logged at debug level).
 */

