        CUDA_Mul12(&_t4, &_t5, (am), (bh));                             \
        CUDA_Mul12(&_t6, &_t7, (am), (bm));                             \
        _t8  = (ah) * (bl);                                             \
        _t9  = (al) * (bh);                                             \
        _t10 = (am) * (bl);                                             \
