    CUDA_Mul233(&p_t_23_0h, &p_t_23_0m, &p_t_23_0l, xh, xm, p_t_22_0h, p_t_22_0m, p_t_22_0l);
    p_resh = p_t_23_0h;
    p_resm = p_t_23_0m;
    p_resl = p_t_23_0l;

    logih = argredtable_pow_cuda[index].logih;
    logim = argredtable_pow_cuda[index].logim;
    logil = argredtable_pow_cuda[index].logil;

    CUDA_Add33(&log2yh, &log2ym, &log2yl, logih, logim, logil, p_resh, p_resm, p_resl);
    CUDA_Add133(&log2xh, &log2xm, &log2xl, ed, log2yh, log2ym, log2yl);

    CUDA_Renormalize3(resh, resm, resl, log2xh, log2xm, log2xl);
}

/* -------- exp2_120: triple-double exp2 (slow path) -------- */

__device__ static __forceinline__
void cuda_crlibm_exp2_120(int* H, double* resh, double* resm, double* resl,
                          double xh, double xm, double xl)
{
    double xhMult2L, rhMult2L, r;
    int k, index1, index2;
    cuda_db_number shiftedxhMult2Ldb;
    double rh, rm, rl;
    double t1h, t1m, t1l, t2, t3;
    double p_t_1_0h, p_t_2_0h, p_t_3_0h, p_t_4_0h;
    double p_t_5_0h, p_t_5_0m;
    double p_t_6_0h, p_t_6_0m;
    double p_t_7_0h, p_t_7_0m;
    double p_t_8_0h, p_t_8_0m;
    double p_t_9_0h,  p_t_9_0m,  p_t_9_0l;
    double p_t_10_0h, p_t_10_0m, p_t_10_0l;
    double p_t_11_0h, p_t_11_0m, p_t_11_0l;
    double p_resh, p_resm, p_resl;
    double tbl1h, tbl1m, tbl1l, tbl2h, tbl2m, tbl2l;
    double tablesh, tablesm, tablesl;
    double exp2h, exp2m, exp2l;

    xhMult2L = xh * CUDA_POW_two13;
    shiftedxhMult2Ldb.d = CUDA_POW_shiftConst + xhMult2L;
    rhMult2L = xhMult2L - (shiftedxhMult2Ldb.d - CUDA_POW_shiftConst);
    r = rhMult2L * CUDA_POW_twoM13;
    k = shiftedxhMult2Ldb.i[CUDA_LO];
    *H = k >> 13;
    index1 = k & CUDA_POW_INDEXMASK1;
    index2 = (k & CUDA_POW_INDEXMASK2) >> 5;
    CUDA_Add12Cond(t1h, t2, r, xm);
    CUDA_Add12Cond(t1m, t1l, t2, xl);
    CUDA_Add12(rh, t3, t1h, t1m);
    CUDA_Add12(rm, rl, t3, t1l);

    p_t_1_0h = CUDA_POW_exp2_120_p6h;
    p_t_2_0h = p_t_1_0h * rh;
    p_t_3_0h = CUDA_POW_exp2_120_p5h + p_t_2_0h;
    p_t_4_0h = p_t_3_0h * rh;
    CUDA_Add12(p_t_5_0h, p_t_5_0m, CUDA_POW_exp2_120_p4h, p_t_4_0h);
    CUDA_MulAdd22(&p_t_6_0h, &p_t_6_0m, CUDA_POW_exp2_120_p3h, CUDA_POW_exp2_120_p3m, rh, rm, p_t_5_0h, p_t_5_0m);
    CUDA_MulAdd22(&p_t_7_0h, &p_t_7_0m, CUDA_POW_exp2_120_p2h, CUDA_POW_exp2_120_p2m, rh, rm, p_t_6_0h, p_t_6_0m);
    CUDA_Mul22(&p_t_8_0h, &p_t_8_0m, p_t_7_0h, p_t_7_0m, rh, rm);
    CUDA_Add23(&p_t_9_0h, &p_t_9_0m, &p_t_9_0l, CUDA_POW_exp2_120_p1h, CUDA_POW_exp2_120_p1m, p_t_8_0h, p_t_8_0m);
    CUDA_Mul33(&p_t_10_0h, &p_t_10_0m, &p_t_10_0l, rh, rm, rl, p_t_9_0h, p_t_9_0m, p_t_9_0l);
    CUDA_Add133(&p_t_11_0h, &p_t_11_0m, &p_t_11_0l, CUDA_POW_exp2_120_p0h, p_t_10_0h, p_t_10_0m, p_t_10_0l);
    CUDA_Renormalize3(&p_resh, &p_resm, &p_resl, p_t_11_0h, p_t_11_0m, p_t_11_0l);

    tbl1h = twoPowerIndex1_cuda[index1].hi;
    tbl1m = twoPowerIndex1_cuda[index1].mi;
    tbl1l = twoPowerIndex1_cuda[index1].lo;
    tbl2h = twoPowerIndex2_cuda[index2].hi;
    tbl2m = twoPowerIndex2_cuda[index2].mi;
    tbl2l = twoPowerIndex2_cuda[index2].lo;

    CUDA_Mul33(&tablesh, &tablesm, &tablesl, tbl1h, tbl1m, tbl1l, tbl2h, tbl2m, tbl2l);
    CUDA_Mul33(&exp2h, &exp2m, &exp2l, tablesh, tablesm, tablesl, p_resh, p_resm, p_resl);

    CUDA_Renormalize3(resh, resm, resl, exp2h, exp2m, exp2l);
}

/* -------- pow_120: combined slow log2+exp2 -------- */

__device__ static __forceinline__
void cuda_crlibm_pow_120(int* H, double* resh, double* resm, double* resl,
                         double* log2xh,
                         double y, int index, double ed, double zh, double zm)
{
    double ylog2xh, ylog2xm, ylog2xl;
    double log2xm, log2xl;

    cuda_crlibm_log2_130(log2xh, &log2xm, &log2xl, index, ed, zh, zm);
    CUDA_Mul133(&ylog2xh, &ylog2xm, &ylog2xl, y, *log2xh, log2xm, log2xl);
    cuda_crlibm_exp2_120(H, resh, resm, resl, ylog2xh, ylog2xm, ylog2xl);
}

/* -------- pow_round_and_check_rn: Ziv test (slow path) -------- */

#define CUDA_ABS(x) ((x) < 0.0 ? -(x) : (x))

__device__ static __forceinline__
int cuda_crlibm_pow_round_and_check_rn(double* pow_out,
                                       int H, double powh, double powm, double powl,
                                       int* G, double* kh, double* kl)
{
    double th, tm, tl;
    int K, K1, K2;
    cuda_db_number twodb, two2db;
    double twoH1074powh, twoH1074powm, shiftedpowh, delta;
    double scaledth;
    double t1m, t1l;

    if ((powh < 1.0) || ((powh == 1.0) && (powm < 0.0))) {
        powh *= 2.0; powm *= 2.0; powl *= 2.0; H--;
    }
    if ((powh > 2.0) || ((powh == 2.0) && (powm >= 0.0))) {
        powh *= 0.5; powm *= 0.5; powl *= 0.5; H++;
    }

    if (H <= -1023) {
        twodb.i[CUDA_HI] = (H + (1074 + 1023)) << 20;
        twodb.i[CUDA_LO] = 0;
        twoH1074powh = twodb.d * powh;
        twoH1074powm = twodb.d * powm;
        shiftedpowh = CUDA_CRLIBM_two52 + twoH1074powh;
        th = shiftedpowh - CUDA_CRLIBM_two52;
        delta = twoH1074powh - th;
        CUDA_Add12Cond(tm, tl, delta, twoH1074powm);
        K = -1074;
    } else {
        th = powh * CUDA_CRLIBM_two52;
        tm = powm * CUDA_CRLIBM_two52;
        tl = powl * CUDA_CRLIBM_two52;
        K = H - 52;
    }

    *G  = K;
    *kh = th;
    *kl = tm;

    if (tm > 0.0) { t1m = -tm; t1l = -tl; }
    else          { t1m =  tm; t1l =  tl; }
    delta = CUDA_ABS((0.5 + t1m) - t1l);

    scaledth = th * CUDA_POW_PRECISEROUNDCST;

    if (delta > scaledth) {
        if (CUDA_ABS(tm) >= 0.5) {
            if (CUDA_ABS(tm) == 0.5) {
                if (tm < 0.0) { if (tl < 0.0) th -= 1.0; }
                else          { if (tl > 0.0) th += 1.0; }
            } else {
                if (tm < 0.0) th -= 1.0; else th += 1.0;
            }
        }

        K1 = K >> 1;
        K2 = K - K1;
        twodb.i[CUDA_HI] = (K1 + 1023) << 20;  twodb.i[CUDA_LO] = 0;
        two2db.i[CUDA_HI] = (K2 + 1023) << 20; two2db.i[CUDA_LO] = 0;
        *pow_out = two2db.d * (twodb.d * th);
        return 1;
    }
    return 0;
}

/* -------- pow_exact_rn: slow-path entry (no pow_exact_case fallback) -------- */

__device__ static __forceinline__
double cuda_crlibm_pow_exact_rn(double x, double y, double sign,
                                int index, double ed, double zh, double zm)
{
    int H, G;
    double powh, powm, powl;
    double pow_out;
    double kh, kl;
    double log2xh;

    cuda_crlibm_pow_120(&H, &powh, &powm, &powl, &log2xh, y, index, ed, zh, zm);

    if (cuda_crlibm_pow_round_and_check_rn(&pow_out, H, powh, powm, powl, &G, &kh, &kl))
        return sign * pow_out;

    /* Skipped pow_exact_case (handles bit-exact powers like 4^2). For
     * pow(rp, 1.5) with rp > 0 the result is never exact, so we'd never
     * fire this branch. Fall back to __device__ pow as a last resort —
     * this can introduce ~1 ULP drift but only fires in TMD cases that
     * are vanishingly rare. */
    return sign * pow(x, y);
}

/* -------- main: cuda_crlibm_pow_rn -------- */

__device__ static __forceinline__
double cuda_crlibm_pow_rn(double x, double y)
{
    cuda_db_number xdb, ydb, yhdb, shiftedylog2xhMult2Ldb, powdb, twodb;
    double sign;
    int E, index;
    double log2FastApprox, ed, ylog2xFast, f;
    double yh, yl, ri, logih, logim, yrih, yril, th, zh, zm;
    double p_t_1_0h, p_t_2_0h, p_t_3_0h, p_t_4_0h, p_t_5_0h;
    double p_t_9_0h, p_t_10_0h;
    double p_t_11_0h, p_t_11_0m;
    double p_t_12_0h, p_t_12_0m;
    double log2zh, log2zm;
    double log2yh, log2ym;
    double log2xh, log2xm;
    double ylog2xh, ylog2xm;
    double rh, r;
    int k, index1, index2, H;
    double tbl1, tbl2h, tbl2m;
    double ph;
    double powh, powm;
    double twoH1074powh, twoH1074powm;
    double shiftedpowh, nearestintpowh, delta, deltaint;
    double rest;
    double lowerTerms;
    double temp1;
    double zhSq, zhFour, p35, p46, p36, p7;
    double xSq;

    xdb.d = x;
    ydb.d = y;

    /* Fast rejection of special cases */
    if (((((xdb.i[CUDA_HI] >> 20) + 1) & 0x3ff) <= 1) ||
        ((((ydb.i[CUDA_HI] >> 20) + 1) & 0x3ff) <= 1)) {
        if (x == 1.0)  return 1.0;
        if (y == 0.0)  return 1.0;
        if (y == 1.0)  return x;
        if (y == 2.0)  return x * x;
        if (y == -1.0) return 1.0 / x;

        if ((x == 0.0) && ((ydb.i[CUDA_HI] & 0x7ff00000) != 0x7ff00000)) {
            /* Edge cases for pow(0, y) — for our use case (rp > 0) we
             * never hit this. Punt to __device__ pow. */
            return pow(x, y);
        }
        if ((ydb.i[CUDA_HI] & 0x7ff00000) == 0x7ff00000)
            return pow(x, y);  /* y is NaN/Inf — punt */
        if ((xdb.i[CUDA_HI] & 0x7ff00000) == 0x7ff00000)
            return pow(x, y);  /* x is NaN/Inf — punt */
    }

    /* For our use case x = rp > 0, so sign = 1 */
    if (xdb.i[CUDA_HI] < 0) return pow(x, y);  /* negative x — punt */
    sign = 1.0;

    /* Range reduction of log(x) — same as log_rn */
    E = 0;
    if ((xdb.i[CUDA_HI] & 0xfff00000) == 0) {
        xdb.d *= CUDA_CRLIBM_two52;
        E = -52;
    }

    E += (xdb.i[CUDA_HI] >> 20) - 1023;
    index = (xdb.i[CUDA_HI] & 0x000fffff);
    xdb.i[CUDA_HI] = index | 0x3ff00000;
    index = (index + (1 << (20 - CUDA_CRLIBM_L - 1))) >> (20 - CUDA_CRLIBM_L);

    if (index >= CUDA_CRLIBM_MAXINDEX) {
        xdb.i[CUDA_HI] -= 0x00100000;
        E++;
    }

    ed = (double) E;

    yhdb.i[CUDA_HI] = xdb.i[CUDA_HI];
    yhdb.i[CUDA_LO] = 0;
    yh = yhdb.d;
    yl = xdb.d - yh;

    /* y=3 / y=4 special cases (no early-out for y=1.5) */
    if ((yl == 0) && ((y == 3.0) || (y == 4.0)) && (E > -255)) {
        if (y == 3.0) return sign * (x * (x * x));
        else { xSq = x * x; return sign * (xSq * xSq); }
    }

    index = index & CUDA_CRLIBM_INDEXMASK;

    f = xdb.d - 1.0;
    log2FastApprox = ed + CUDA_POW_logFastCoeff * f;
    ylog2xFast = y * log2FastApprox;

    if (CUDA_ABS(ylog2xFast) >= 1261.0) {
        if (ylog2xFast > 0.0)
            return (sign * CUDA_POW_LARGEST) * CUDA_POW_LARGEST;
        else
            return (sign * CUDA_POW_SMALLEST) * CUDA_POW_SMALLEST;
    }

    if (CUDA_ABS(ylog2xFast) <= CUDA_POW_twoM55)
        return sign * (1.0 + CUDA_POW_SMALLEST);

    ri    = (double) argredtable_pow_cuda[index].ri;
    logih = argredtable_pow_cuda[index].logih;
    logim = argredtable_pow_cuda[index].logim;

    yrih = yh * ri;
    yril = yl * ri;
    th   = yrih - 1.0;
    CUDA_Add12Cond(zh, zm, th, yril);

    /* Polynomial approximation of log2(1 + (zh + zm)) (fast path) */
    zhSq = zh * zh;
    p35 = CUDA_POW_log2_70_p3h + zhSq * CUDA_POW_log2_70_p5h;
    p46 = CUDA_POW_log2_70_p4h + zhSq * CUDA_POW_log2_70_p6h;
    zhFour = zhSq * zhSq;
    p36 = p35 + zh * p46;
    p7  = CUDA_POW_log2_70_p7h * zhFour;
    p_t_9_0h = p36 + p7;

    p_t_10_0h = p_t_9_0h * zh;
    CUDA_Add212(&p_t_11_0h, &p_t_11_0m, CUDA_POW_log2_70_p2h, CUDA_POW_log2_70_p2m, p_t_10_0h);
    CUDA_MulAdd22(&p_t_12_0h, &p_t_12_0m, CUDA_POW_log2_70_p1h, CUDA_POW_log2_70_p1m, zh, zm, p_t_11_0h, p_t_11_0m);
    CUDA_Mul22(&log2zh, &log2zm, p_t_12_0h, p_t_12_0m, zh, zm);

    CUDA_Add122(&log2yh, &log2ym, ed, logih, logim);
    CUDA_Add22(&log2xh, &log2xm, log2yh, log2ym, log2zh, log2zm);

    CUDA_Mul12(&ylog2xh, &temp1, y, log2xh);
    ylog2xm = temp1 + y * log2xm;

    /* exp2(ylog2xh + ylog2xm) — fast path */
    shiftedylog2xhMult2Ldb.d = CUDA_POW_shiftConstTwoM13 + ylog2xh;
    r = ylog2xh - (shiftedylog2xhMult2Ldb.d - CUDA_POW_shiftConstTwoM13);
    k = shiftedylog2xhMult2Ldb.i[CUDA_LO];
    H = k >> 13;
    index1 = k & CUDA_POW_INDEXMASK1;
    index2 = (k & CUDA_POW_INDEXMASK2) >> 5;

    rh = r + ylog2xm;

    tbl1  = twoPowerIndex1_cuda[index1].hiM1;
    tbl2h = twoPowerIndex2_cuda[index2].hi;
    tbl2m = twoPowerIndex2_cuda[index2].mi;

    p_t_1_0h = CUDA_POW_exp2_p_p3h;
    p_t_2_0h = p_t_1_0h * rh;
    p_t_3_0h = CUDA_POW_exp2_p_p2h + p_t_2_0h;
    p_t_4_0h = p_t_3_0h * rh;
    p_t_5_0h = CUDA_POW_exp2_p_p1h + p_t_4_0h;
    ph = p_t_5_0h * rh;

    lowerTerms = tbl1 + (ph + tbl1 * ph);
    CUDA_Add212(&powh, &powm, tbl2h, tbl2m, tbl2h * lowerTerms);

    if (H >= 1025) return (sign * CUDA_POW_LARGEST) * CUDA_POW_LARGEST;
    if (H <= -1077) return (sign * CUDA_POW_SMALLEST) * CUDA_POW_SMALLEST;

    if (H > -1022) {
        if (powh == (powh + (powm * CUDA_CRLIBM_RNROUNDCST))) {
            powdb.d = powh;
            if (H < 1023) {
                powdb.i[CUDA_HI] += H << 20;
                return sign * powdb.d;
            } else {
                powdb.i[CUDA_HI] += (H - 3) << 20;
                return sign * powdb.d * 8.0;
            }
        }
    } else {
        /* Subnormal-range handling */
        if ((powh < 1.0) || ((powh == 1.0) && (powm < 0.0))) {
            powh *= 2.0; powm *= 2.0; H--;
        }
        if ((powh > 2.0) || ((powh == 2.0) && (powm >= 0.0))) {
            powh *= 0.5; powm *= 0.5; H++;
        }
        if (H > -1023) {
            if (powh == (powh + (powm * CUDA_CRLIBM_RNROUNDCST))) {
                powdb.d = powh;
                powdb.i[CUDA_HI] += H << 20;
                return sign * powdb.d;
            }
        } else {
            twodb.i[CUDA_HI] = (H + (1074 + 1023)) << 20;
            twodb.i[CUDA_LO] = 0;
            twoH1074powh = twodb.d * powh;
            twoH1074powm = twodb.d * powm;
            shiftedpowh   = CUDA_CRLIBM_two52 + twoH1074powh;
            nearestintpowh = shiftedpowh - CUDA_CRLIBM_two52;
            deltaint = twoH1074powh - nearestintpowh;
            delta = deltaint + twoH1074powm;
            if (CUDA_ABS(delta) > 0.5) {
                if (delta > 0.0) { nearestintpowh += 1.0; delta -= 1.0; }
                else             { nearestintpowh -= 1.0; delta += 1.0; }
            }
            rest = CUDA_ABS(0.5 - CUDA_ABS(delta));
            if (rest * CUDA_POW_SUBNORMROUNDCST > twodb.d) {
                twodb.d = nearestintpowh + CUDA_CRLIBM_two52;
                twodb.i[CUDA_HI] = (twodb.i[CUDA_HI] + (1 << 20)) & 0x001fffff;
                return sign * twodb.d;
            }
        }
    }

    /* Slow path */
    return cuda_crlibm_pow_exact_rn(x, y, sign, index, ed, zh, zm);
}

#endif /* NBODY_CUDA_CRLIBM_CUH */
